import React from "react";
import "./IncomeCategory.css";

function IncomeCategory({ onNext, updateData }) {

  const selectCategory = (category) => {
    updateData({ incomeCategory: category });
    onNext();
  };

  const categories = [
    { name: "Fixed Income", desc: "Salary or stable monthly income" },
    { name: "Variable Income", desc: "Income changes month to month" },
    { name: "Freelancer/Gig", desc: "Project based earnings" },
    { name: "Business Owner", desc: "Own business income" },
    { name: "No Income", desc: "Currently no earnings" },
    { name: "Multiple Sources", desc: "More than one income source" }
  ];

  return (
    <div className="income-container">
      <h1 className="income-title">Select Your Income Category</h1>
      <p className="income-subtitle">Choose one option to continue</p>

      <div className="income-grid">
        {categories.map((item, index) => (
          <div
            key={index}
            className="income-card"
            onClick={() => selectCategory(item.name)}
          >
            <div className="income-icon">💼</div>
            <div className="income-name">{item.name}</div>
            <div className="income-desc">{item.desc}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default IncomeCategory;
